import"./modulepreload-polyfill-B5Qt9EMX.js";import{m as i}from"./foundation-module-BgS6mBLm.js";import{h as r,p as s,i as e}from"./content-helpers-BfuPXrd1.js";const a='<div class="fm-code-card"><strong>Main program</strong><code>when green flag clicked<br>setup scene<br>repeat until &lt;goal reached&gt;<br>&nbsp;&nbsp;move player<br>&nbsp;&nbsp;check obstacle<br>&nbsp;&nbsp;update score</code></div>',n={id:"MOD-SCRATCH-DECOMPOSITION-01",slug:"scratch-decomposition",version:"0.1.0",storageKey:"mod-scratch-decomposition-01-v0.1.0",mark:"S7",shortTitle:"Scratch decomposition",title:"Scratch Decomposition, Loops, and Lists",gradeLabel:"Grades 7–8 Technology",classes:["7A","7B","8A","8B"],sections:[{id:"start",short:"Start",title:"Plan code in smaller parts",summary:"Use decomposition, custom blocks, loops, lists, and testing to make Scratch code easier to build.",minutes:5,html:`<section class="fm-opening"><div><p class="fm-label">Goal</p><h2>Give each part of the program one job</h2><p>Long scripts are difficult to read and fix. A plan with named subroutines and a clear main program makes the work checkable.</p></div>${a}</section><section class="fm-block"><p class="fm-label">Before you begin</p><h2>What you need and what you will save</h2><div class="fm-concept-grid"><div><h3>Know</h3><p>Events, sequence, conditions, variables, and basic Scratch blocks.</p></div><div><h3>Use</h3><p>A computer with Scratch online or the Scratch desktop app.</p></div><div><h3>Build</h3><p>A small project with a main program, named custom blocks, and a suitable loop.</p></div><div><h3>Save</h3><p>The .sb3 file or share link, a typed test record, and this practice report.</p></div></div></section>`},{id:"decompose-learn",short:"Learn decomposition",title:"Break the problem into subroutines",summary:"Name the jobs before choosing the blocks.",minutes:15,html:`<section class="fm-block"><p class="fm-label">Learn</p><h2>Decomposition turns one large problem into smaller jobs</h2>${a}<div class="fm-concept-grid"><div><h3>Main program</h3><p>Controls when the parts run.</p></div><div><h3>Custom block</h3><p>A named subroutine that completes one job.</p></div><div><h3>Event</h3><p>Starts code after an action.</p></div><div><h3>Condition</h3><p>Checks whether a rule is true.</p></div></div></section>`},s("decompose-practice","Decompose practice","Practice breaking down a Scratch task","Choose the clearest subroutine or main-program decision.",[e("Name one job","Which custom block name describes one clear job?",["move player","do everything","stuff"],0,"Name a subroutine","move player states exactly what that block should do.","Use a verb and the object it changes."),e("Keep the main program clear","Where should the program call setup scene?",["Near the start of the main program","Inside every movement block","Only after the project ends"],0,"Order the main program","Setup belongs before the repeated game actions.","The scene must exist before the player uses it."),e("Choose an event","What starts a script when the player presses the space key?",["when space key pressed","wait 1 second","broadcast game over"],0,"Choose an event","The key event responds directly to the player's input.","Match the trigger to the action."),e("Separate jobs","A script moves the player, checks a wall, and updates score. What is the clearest plan?",["Use three named subroutines","Put every block in one custom block called code","Duplicate the whole script"],0,"Separate responsibilities","Three named jobs make the program easier to trace and fix.","Each part should have one main purpose."),e("Call a subroutine","What happens when the main program calls check obstacle?",["The blocks in that custom block run","The project deletes the block","The sprite always stops"],0,"Trace a custom block call","Calling the custom block runs its stored instructions.","A call transfers control to the named job.")]),{id:"loops-learn",short:"Learn loops",title:"Choose a loop that matches the task",summary:"Use repeat, forever, or repeat until deliberately.",minutes:15,html:'<section class="fm-block"><p class="fm-label">Compare</p><h2>Different loops answer different questions</h2><div class="fm-concept-grid"><div><h3>repeat 10</h3><p>Run an exact number of times.</p></div><div><h3>forever</h3><p>Keep running until the project stops.</p></div><div><h3>repeat until</h3><p>Stop when a condition becomes true.</p></div><div><h3>List</h3><p>Store related values under one name.</p></div></div></section>'},s("loops-practice","Loop practice","Practice loops and lists","Choose the construct that fits each situation.",[e("Ten steps","A sprite must take exactly ten steps. Which loop fits?",["repeat 10","forever","repeat until touching goal"],0,"Choose count-controlled iteration","repeat 10 gives an exact number of repetitions.","The task states a fixed count."),e("Keep checking","The game must keep checking keyboard input while it runs. Which loop fits?",["forever","repeat 2","wait until timer = 0"],0,"Choose continuous iteration","A forever loop keeps checking until the project stops.","No fixed ending condition was given."),e("Stop at the goal","Movement should stop when the sprite touches the goal. Which loop fits?",["repeat until touching goal","repeat 3","forever without a condition"],0,"Choose condition-controlled iteration","repeat until uses the goal condition as the stopping rule.","Look for the stated condition."),e("Store questions","What should hold five quiz questions under one name?",["A list","A costume","A broadcast"],0,"Use a list","A list stores a collection of related items.","The task needs several values, not one."),e("Choose an item","Which block reads the third value in a list named questions?",["item 3 of questions","length of questions","delete all of questions"],0,"Access a list item","item 3 returns the value at position three.","Choose the block that reads one position.")]),{id:"debug-learn",short:"Learn debugging",title:"Test one part at a time",summary:"Trace the expected result, observe the actual result, and change one cause.",minutes:12,html:'<section class="fm-block"><p class="fm-label">Debug</p><h2>A useful test has an input and an expected result</h2><ol class="fm-steps"><li><p>Choose one feature.</p></li><li><p>State the input or action.</p></li><li><p>Predict the expected result.</p></li><li><p>Run the test and record the actual result.</p></li><li><p>Change one likely cause, then retest.</p></li></ol></section>'},s("debug-practice","Debug practice","Practice finding a useful next step","Choose the best test or correction for each problem.",[e("Block never runs","A custom block exists but nothing happens. What should you check first?",["Whether the main program calls it","The sprite color","The project title"],0,"Trace the call","A custom block will not run unless another script calls it.","Follow the control flow from the starting event."),e("Loop never stops","A repeat until loop never ends. What should you inspect?",["Whether its condition can become true","The font size","The backdrop name"],0,"Inspect a stopping condition","The loop continues if its condition never becomes true.","Focus on the rule that should stop repetition."),e("Score changes twice","One click adds two points. What is a likely cause?",["Two scripts respond to the same click","The stage is too wide","The list has one item"],0,"Find duplicate event logic","Two event scripts can both change the score.","Look for repeated code triggered by one action."),e("Test clearly","Which test record is most useful?",["Press space: expected jump once; actual jump twice","It is broken","Tried stuff"],0,"Record expected and actual results","The first record names the action and observable difference.","A test should be repeatable by another person."),e("Retest fairly","After one change, what should you do next?",["Repeat the same test","Change three more things","Delete the project"],0,"Retest one change","Repeating the test shows whether that change caused an improvement.","Keep the test condition stable.")]),{id:"build-record",short:"Record build",title:"Record a Scratch build",summary:"Describe the code structure and one test result from the saved project.",minutes:15,kind:"form",prompt:"Record checkable Scratch evidence",fields:[{name:"filename",label:"Scratch project filename or share link"},{name:"main",label:"What does the main program control?",type:"textarea",rows:2},{name:"subroutines",label:"Name three subroutines and the job of each.",type:"textarea",rows:4},{name:"loop",label:"Which loop did you use, and why does it fit?",type:"textarea",rows:3},{name:"test",label:"Record one input, expected result, actual result, and correction.",type:"textarea",rows:4}]},{id:"review",short:"Review",title:"Check the Scratch project before you submit",summary:"Review the program structure, test evidence, and saved file.",minutes:10,html:'<section class="fm-block"><p class="fm-label">Review</p><h2>Can another person follow the program?</h2><ul class="fm-checklist"><li>The green-flag or starting event reaches the main program.</li><li>Each custom block has a clear verb-and-object name and one main job.</li><li>The loop matches the task: fixed count, continuous check, or condition-controlled stop.</li><li>The test record includes input, expected result, actual result, and one correction.</li><li>The saved .sb3 file or share link opens on the computer.</li></ul></section><section class="fm-block"><p class="fm-label">Common mistakes</p><h2>Fix these before exporting</h2><div class="fm-concept-grid"><div><h3>Unused custom block</h3><p>Call it from the main program or another active script.</p></div><div><h3>Forever by accident</h3><p>Use repeat until when the action needs a clear stopping condition.</p></div><div><h3>Several changes at once</h3><p>Change one likely cause, then repeat the same test.</p></div><div><h3>Vague test note</h3><p>Name the input and the visible result so another person can repeat it.</p></div></div></section><section class="fm-note"><strong>Next:</strong> revisit the practice page connected to your weakest test. Then open History & export and download the report your teacher assigned.</section>'},r]};i(n);document.addEventListener("submit",t=>{if(t.target.id!=="fm-choice-form"||t.target.querySelector('input[name="answer"]:checked'))return;t.preventDefault(),t.stopImmediatePropagation();const o=t.target.querySelector('input[name="answer"]');o.setCustomValidity("Choose an answer before saving."),o.reportValidity(),o.addEventListener("change",()=>o.setCustomValidity(""),{once:!0})},!0);
